# Sourced by new-customer.sh and update-customers.sh.
#
# ensure_vapid_keys <install dir>: gives the install its phone-notification
# keys (NOT-228) when its backend.env has none. Never replaces existing keys:
# every phone subscribed with the old ones would silently stop receiving.
ensure_vapid_keys() {
  local dir="$1" env="$1/backend.env" host keys
  grep -q '^VAPID_PUBLIC_KEY=.' "$env" && return 0

  host="$(sed -n 's/^HOST=//p' "$dir/.env")"
  # Generated by the backend image itself, which ships web-push; the server
  # needs no Node.
  keys="$(docker run --rm --entrypoint node nms-backend:latest -e \
    "const k=require('web-push').generateVAPIDKeys();console.log(k.publicKey,k.privateKey)")"
  [ -n "$keys" ] || {
    echo "error: could not generate VAPID keys" >&2
    return 1
  }

  sed -i '/^VAPID_\(PUBLIC_KEY\|PRIVATE_KEY\|SUBJECT\)=/d' "$env"
  {
    echo "VAPID_PUBLIC_KEY=${keys% *}"
    echo "VAPID_PRIVATE_KEY=${keys#* }"
    echo "VAPID_SUBJECT=https://$host"
  } >>"$env"
  echo "  phone notifications: VAPID keys added to $env"
}
